const data=await fetch('content.json').then(r=>{if(!r.ok)throw Error('Content unavailable');return r.json()});
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Browser storage unavailable; changes last for this visit.')}}
let state=read('cityjs-coding-progress',{}),notes=read('cityjs-coding-notes',{}),drafts=read('cityjs-coding-prompts',{}),evidence=read('cityjs-coding-evidence',{}),timer=null,remaining=0,current='overview';
let toastId;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastId);toastId=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function highlight(code){return code.split(/(#[^\n]*|\/\/[^\n]*|'[^'\n]*'|"[^"\n]*"|\b(?:const|return|export|function|import|from|if|else|true|false|async|await|type|interface)\b|\b\d+\b)/g).map(x=>{const c=/^(#|\/\/)/.test(x)?'comment':/^['"]/.test(x)?'string':/^\d+$/.test(x)?'num':/^(const|return|export|function|import|from|if|else|true|false|async|await|type|interface)$/.test(x)?'key':'';return c?`<span class="tok-${c}">${esc(x)}</span>`:esc(x)}).join('')}
let codeCount=0;function code(text){const id=`code-${++codeCount}`;return `<div class="code"><button class="copy" data-copy="${id}">Copy</button><pre><code id="${id}">${highlight(text)}</code></pre></div>`}
const paragraphs=arr=>arr.map(t=>`<p>${esc(t)}</p>`).join('');
const list=arr=>`<ul>${arr.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`;
function sources(ids){return `<div class="source-links" aria-label="Official documentation">${ids.map(id=>{const s=data.sources.find(x=>x.id===id);return `<a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`}).join('')}</div>`}
const schedule=[['09:00–09:10',10,'Opening: generated code versus a verified change','overview'],...data.labs.slice(0,4).map(l=>[l.clock,l.minutes,`${l.id} · ${l.title}`,l.id]),['10:30–10:40',10,'Break','break'],...data.labs.slice(4).map(l=>[l.clock,l.minutes,`${l.id} · ${l.title}`,l.id]),['11:55–12:00',5,'Debrief and next steps','finish']];
const chapters=[['overview','Workshop roadmap'],['setup','Before you arrive'],['project','Project & acceptance'],...data.labs.slice(0,4).map(l=>[l.id,l.title]),['break','Break & checkpoint'],...data.labs.slice(4).map(l=>[l.id,l.title]),['finish','Finish & next steps'],['toolkit','Templates & downloads'],['sources','Sources & verification']];
function section(id,html){return `<section class="chapter" id="chapter-${id}" data-chapter="${id}" hidden>${html}</section>`}
function overview(){return `<span class="kicker">CityJS · Attendee workbook · 180 minutes</span><h1>Build it.<br><em>Verify it.</em></h1><p class="lead">Deep dive into Agentic Coding with Codex / Claude. Eight practical labs. One React session planner. Your decisions, your code, your evidence.</p><div class="actions"><a class="action" href="#setup">Get ready →</a><a class="action secondary" href="#01">Start lab 01</a><a class="action secondary" href="demo/" target="_blank" rel="noopener">Try the reference app ↗</a><a class="action secondary" href="https://github.com/shivaylamba/cityjs-agentic-coding-workshop" target="_blank" rel="noopener">Public GitHub ↗</a></div><div class="meta-strip"><div><strong>8</strong><span>hands-on labs</span></div><div><strong>180 min</strong><span>including opening, break and close</span></div><div><strong>1 app</strong><span>built from an empty repository</span></div></div><h2>How you will work</h2><p>Choose Codex or Claude Code. Work in pairs: one drives, one checks assumptions and results. Read the concept, make a product decision, delegate a bounded task, inspect the diff, run the experiment and collect evidence. Switch roles after the break.</p><p>The editable prompts are starting points. Change them to reflect your decisions and actual files. Copying a prompt without checking the output does not complete a lab.</p><h2>The three-hour roadmap</h2><div class="table-wrap"><table><thead><tr><th>Clock</th><th>Minutes</th><th>Activity</th></tr></thead><tbody>${schedule.map(([t,m,n,id])=>`<tr><td>${t}</td><td>${m}</td><td><a href="#${id}">${esc(n)}</a></td></tr>`).join('')}</tbody></table></div><div class="panel soft"><h3>What you will build</h3><p>A fictional CityJS programme with a personal agenda, clash prevention, filters, favorites and export. The coding agents help develop the app; the app has no runtime AI calls or model keys.</p><p class="fine">The complete reference is a recovery aid. Start the main exercises in your own empty repository. Record when you use a recovery solution.</p></div>`}
function setup(){return `<span class="kicker">Prework · complete before the session</span><h1>Ready to build.</h1><p class="lead">Install and authenticate one coding agent before arriving. Choose Codex or Claude Code; you do not need both.</p>${list(['Node.js 24 LTS, npm, Git, a code editor and a browser.','Working authenticated access to your chosen coding agent, with usage available.','A GitHub account for remote CI/PRs and a Vercel account if you want your own deployment.','Install Playwright Chromium before class. One browser worker, one app server, at most two agent sessions.','Use fictional data and a test project. Keep credentials out of source, prompts and the frontend.'])}<h2>Check your tools</h2>${code('node --version\nnpm --version\ngit --version\ncodex --version\n# Or:\nclaude --version')}<p>Use the official <a href="https://developers.openai.com/codex/quickstart" target="_blank" rel="noopener">Codex setup</a> or <a href="https://code.claude.com/docs/en/quickstart" target="_blank" rel="noopener">Claude Code setup</a>. Try a small file edit and test command in a disposable folder first.</p><h2>Preflight the reference</h2><p>Download the packet and keep its reference folder separate from your empty workshop project.</p>${code('cd reference\nnpm ci\nnpx playwright install chromium\nnpm run check\nnpm run test:e2e\nnpm run dev')}<p>Use the Local URL Vite prints, normally http://127.0.0.1:5173. Stop with Ctrl-C. These preflight results apply to the reference, not to code you will generate later.</p><h2>If setup is blocked</h2><p>Pair with someone who has working access. Use the reference in a separate recovery folder and record that choice. If the agent sandbox denies the browser-test server with listen EPERM, run the same check in your authorised host terminal and keep the blocked result in your log. Do not bypass permissions or mark unrun checks passed.</p>${sources(['codex-security','claude-permissions'])}`}
function project(){return `<span class="kicker">One project · deliberately bounded</span><h1>CityJS<br>Session Planner.</h1><p class="lead">Help an attendee choose what to attend, without pretending to reserve a seat.</p><div class="actions"><a class="action" href="demo/" target="_blank" rel="noopener">Open the reference app ↗</a><a class="action secondary" href="downloads/spec.md" download>Download example spec</a></div><h2>The fictional programme</h2><div class="table-wrap"><table><thead><tr><th>Time</th><th>Session</th><th>Room</th></tr></thead><tbody><tr><td>09:00–09:30</td><td>Opening the agent loop</td><td>Athena</td></tr><tr><td>09:15–09:45</td><td>Concurrent choices</td><td>Hermes</td></tr><tr><td>09:30–10:00</td><td>Spec clinic</td><td>Athena</td></tr><tr><td>10:00–10:30</td><td>Review before release</td><td>Hermes</td></tr><tr><td>10:30–11:00</td><td>The sold-out session · full</td><td>Athena</td></tr><tr><td>11:00–11:30</td><td>Ship it, “carefully” — Αθήνα</td><td>Hermes</td></tr></tbody></table></div><p class="fine">Not the real CityJS programme. One demo day; Europe/Athens local clock minutes. No timestamp or timezone conversion is needed for this exercise.</p><h2>The rule that makes the demo interesting</h2><p>One attendee cannot be in overlapping sessions, even in different rooms. A session ending at 09:30 and one starting at 09:30 are allowed. Decide this boundary before inspecting the implementation.</p>${code('export function overlaps(a: Session, b: Session) {\n  return a.startMinute < b.endMinute\n      && b.startMinute < a.endMinute;\n}')}<p class="fine">The strict comparisons implement half-open intervals. Change either to ≤ and write a boundary test: a plausible single-character edit changes the product behaviour.</p><h2>Eight acceptance boundaries</h2><ol><li>Real fixture IDs, titles, rooms, times and availability.</li><li>Add/remove with rejection of duplicate and full sessions.</li><li>Reject clashes; allow back-to-back; reject malformed intervals.</li><li>Reload-safe local agenda and favorites; recover from corrupt or stale storage.</li><li>Title search and room filters compose with AND.</li><li>Favorites are independent of agenda; favorites-only composes with other filters.</li><li>Ordered plain-text export; exact titles; empty state without a download.</li><li>Keyboard/narrow-screen use, real checks and hosted verification.</li></ol><h2>What attendees must work out</h2><p>Choose conflict feedback and an empty-agenda experience. Add a new acceptance example. Negotiate file ownership, challenge a proposed plan, design a regression, and make a release decision. The task prompts are editable starting points, not answers to paste blindly.</p><h2>Production boundary</h2><p>A static app with browser-local storage is appropriate for this personal-planner demonstration. It is not a production booking system. Durable multi-user data, backend validation, authentication, privacy, monitoring, incident response, dependency maintenance and load testing belong to a follow-up phase. We teach production engineering habits without claiming three hours covers every operational requirement.</p>`}
function teachingPage(l){return `<h2>Understand before building</h2><p class="fine">Read the concept and worked example before the task. During the live session, use the scheduled explanation block; optional detail is available for preparation and review.</p><div class="teaching">${(l.teaching??[]).map(b=>`<article class="panel"><h3>${esc(b.title)}</h3><p>${esc(b.text)}</p>${code(b.code)}<p>${esc(b.walkthrough)}</p><p><b>Check your understanding:</b> ${esc(b.question)}</p><details><summary>Expected reasoning</summary><p>${esc(b.answer)}</p></details></article>`).join('')}</div>`}
function labPage(l){return `<div class="lab-top"><span class="kicker">Lab ${l.id}</span><span class="badge">${l.clock}</span><span class="badge">${l.minutes} minutes total</span></div><h1>${esc(l.title)}.</h1><p class="lab-goal">${esc(l.goal)}</p><div class="lab-toolbar"><label class="complete-label"><input class="complete" data-lab="${l.id}" type="checkbox" ${state[l.id]?'checked':''}> Mark this lab complete</label><div class="timer"><output aria-label="Lab time remaining" id="timer-${l.id}">${l.minutes}:00</output><button data-timer="${l.id}">Start timer</button><button data-reset="${l.id}">Reset</button></div></div><p class="fine">Completion is your own progress marker, not automated verification. Tick evidence below only after observing it.</p><div class="budget">${l.budget.map((m,i)=>`<div><strong>${m} min</strong><span>${['Explain & demonstrate','Build & inspect','Experiment','Debrief'][i]}</span></div>`).join('')}</div><h2>The concept, in this app</h2><div class="concepts">${paragraphs(l.concept)}</div>${teachingPage(l)}<h2>Your build sequence</h2><div class="steps">${l.steps.map(st=>`<div class="step"><div><h3>${esc(st.title)}</h3><p>${esc(st.text)}</p>${st.code?code(st.code):''}</div></div>`).join('')}</div><div class="prompt"><div class="prompt-head"><h3>An editable task contract</h3><button data-prompt-copy="${l.id}">Copy prompt</button></div><p class="fine">Read it first. Add your decisions, scope and actual file names. Saved locally in this browser.</p><label class="sr-label" for="prompt-${l.id}">Prompt for lab ${l.id}</label><textarea id="prompt-${l.id}" data-prompt="${l.id}" spellcheck="false">${esc(drafts[l.id]??l.prompt)}</textarea></div><h2>Evidence before moving on</h2><ul class="evidence">${l.checks.map((c,i)=>`<li><input aria-label="Evidence ${i+1} for lab ${l.id}" type="checkbox" data-evidence="${l.id}-${i}" ${evidence[`${l.id}-${i}`]?'checked':''}><span>${esc(c)}</span></li>`).join('')}</ul><div class="experiment"><span class="kicker">Think first. Then try it.</span><h3>The experiment</h3><p>${esc(l.experiment)}</p></div><h2>Explain what you learned</h2>${list(l.questions)}<details class="recovery"><summary>If you get stuck</summary><p>${esc(l.recovery)}</p></details><p class="fine"><b>Files or evidence:</b> ${l.files.map(f=>`<code>${esc(f)}</code>`).join(' · ')}</p>${sources(l.refs)}<div class="notebook"><h3>Your decision & evidence log</h3><label for="notes-${l.id}" class="fine">Prediction → observation → decision → what remains unverified</label><textarea id="notes-${l.id}" data-note="${l.id}" placeholder="Write what you decided and what you actually observed…">${esc(notes[l.id]??'')}</textarea></div>`}
function breakPage(){return `<span class="kicker">10:30–10:40 · 10 minutes</span><h1>Save your checkpoint.</h1><p class="lead">Take a break, then switch pair roles.</p>${list(['Save and commit the first working slice before creating worktrees.','Stop unused dev servers and browser workers.','If blocked, continue from the reference in a separate folder and record recovery use.','Resume at 10:40 with the agreed feature contracts ready.'])}`}
function finish(){return `<span class="kicker">11:55–12:00 · 5 minutes</span><h1>Explain your evidence.</h1><p class="lead">Finish with a decision you made, a failure you reproduced and a result you verified.</p>${list(['Name one product decision you made before the agent edited code.','Show a check that rejected a bad candidate.','Compare your supervision style with another pair, stating differences in model, context or environment.','Record one task you would delegate and one action you would keep under direct human control.','Record the actual candidate SHA, hosted URL if deployed, check results and remaining limitations.'])}<p>This is a browser-local planner demonstration. Durable backend data, authentication, privacy, monitoring, load testing and operational ownership remain follow-up work for a real booking service.</p><button data-export-notes>Export my learning log</button>`}
function toolkit(){return `<span class="kicker">Attendee materials</span><h1>Take the useful files.</h1><div class="download-list"><a href="https://github.com/shivaylamba/cityjs-agentic-coding-workshop" target="_blank" rel="noopener">Public workshop repository ↗<small>Attendee workbook, labs, templates, reference app and checks.</small></a><a href="workshop-packet.zip" download>Download the attendee packet (.zip)<small>Eight handouts, context/spec/Skill templates, scorecard and complete reference app. No delivery scripts.</small></a><a href="downloads/spec.md" download>Example specification</a><a href="downloads/AGENTS.md.txt" download>Project working agreement</a><a href="downloads/CLAUDE.md.txt" download>Claude compatibility import</a><a href="downloads/SKILL.md.txt" download>Release-check Skill</a><a href="downloads/experiment-scorecard.md" download>Guided/autonomous scorecard</a><a href="downloads/release-evidence.md" download>Release evidence template</a><a href="demo/" target="_blank" rel="noopener">Complete reference demo ↗</a></div><h2>Choose the path for your client</h2><div class="table-wrap"><table><thead><tr><th>Need</th><th>Codex</th><th>Claude Code</th></tr></thead><tbody><tr><td>Project context</td><td>AGENTS.md</td><td>CLAUDE.md importing @AGENTS.md for compatibility</td></tr><tr><td>Project Skill</td><td>.agents/skills/release-check/SKILL.md</td><td>.claude/skills/release-check/SKILL.md</td></tr><tr><td>Explicit Skill invocation in chat</td><td>$release-check</td><td>/release-check</td></tr><tr><td>Independent work</td><td colspan="2">Separate Git worktrees and sessions; one integration owner</td></tr></tbody></table></div><p class="fine">Current client versions and organisation settings can differ. Check actual discovery and tool calls instead of assuming a configured integration ran.</p>`}
function sourcePage(){return `<span class="kicker">Sources & verification</span><h1>Check the facts.</h1><p>Official sources checked on ${data.reviewed}. The teaching sequence is a workshop design, not a vendor-prescribed workflow.</p><div class="source-list">${data.sources.map(s=>`<article><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.note)}</p></article>`).join('')}</div><h2>Verification scope</h2><p><a href="validation.json" target="_blank" rel="noopener">Read the validation report ↗</a></p><p>Reference tests do not certify every model-generated implementation. Perform the actual Skill/MCP calls in your own client, distinguish host checks from sandbox-blocked checks, and verify your own deployed origin. A timed beginner rehearsal and a real operational booking service are outside this package.</p>`}
$('#main').innerHTML=section('overview',overview())+section('setup',setup())+section('project',project())+data.labs.slice(0,4).map(l=>section(l.id,labPage(l))).join('')+section('break',breakPage())+data.labs.slice(4).map(l=>section(l.id,labPage(l))).join('')+section('finish',finish())+section('toolkit',toolkit())+section('sources',sourcePage());
function updateNav(filter=''){const q=filter.toLowerCase().trim();const shown=chapters.filter(([id,t])=>!q||`${id} ${t} ${JSON.stringify(data.labs.find(l=>l.id===id)??{})}`.toLowerCase().includes(q));$('#navigation').innerHTML=shown.length?shown.map(([id,t])=>`<a href="#${id}" ${id===current?'aria-current="page"':''} class="${id===current?'active':''}"><span class="num">${/^\d/.test(id)?id:'—'}</span><span>${esc(t)}</span>${state[id]?'<span class="done" aria-label="marked complete">✓</span>':''}</a>`).join(''):'<p class="no-results">No matching chapter.</p>';const count=data.labs.filter(l=>state[l.id]).length;$('#progress').textContent=`${count} / 8 labs marked complete`;$('#progress-fill').style.width=`${count/8*100}%`}
function setRoute(){let id=decodeURIComponent(location.hash.slice(1)||'overview');if(!chapters.some(x=>x[0]===id))id='overview';if(timer){clearInterval(timer);timer=null}current=id;document.querySelectorAll('.chapter').forEach(x=>x.hidden=x.dataset.chapter!==id);const i=chapters.findIndex(x=>x[0]===id);$('#previous').disabled=i===0;$('#next').disabled=i===chapters.length-1;$('#location').textContent=`${i+1} / ${chapters.length} · ${chapters[i][1]}`;document.title=`${chapters[i][1]} · CityJS Agentic Coding`;document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');document.querySelectorAll('[data-timer]').forEach(b=>b.textContent='Start timer');updateNav($('#search').value);window.scrollTo(0,0)}
function syncDrawer(){document.getElementById('rail').inert=matchMedia('(max-width:760px)').matches&&!document.body.classList.contains('menu-open')}
window.addEventListener('resize',syncDrawer);window.addEventListener('hashchange',()=>{setRoute();syncDrawer()});$('#search').addEventListener('input',e=>updateNav(e.target.value));$('#menu').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open));syncDrawer()};$('#print').onclick=()=>window.print();
function navigate(delta){const i=chapters.findIndex(x=>x[0]===current);if(chapters[i+delta])location.hash=chapters[i+delta][0]}
$('#previous').onclick=()=>navigate(-1);$('#next').onclick=()=>navigate(1);window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowRight')navigate(1);if(e.key==='ArrowLeft')navigate(-1);if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');syncDrawer()}});
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{toast('Clipboard unavailable. Select the text and copy manually.')}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.copy)copy(document.getElementById(b.dataset.copy).textContent);if(b.dataset.promptCopy)copy(document.getElementById(`prompt-${b.dataset.promptCopy}`).value);if(b.hasAttribute('data-export-notes')){const text=data.labs.map(l=>`# ${l.id} ${l.title}\nMarked complete: ${!!state[l.id]}\n\n${notes[l.id]??'(No notes)'}\n`).join('\n');const u=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));const a=document.createElement('a');a.href=u;a.download='cityjs-my-learning-log.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}if(b.dataset.timer){const id=b.dataset.timer;if(timer){clearInterval(timer);timer=null;b.textContent='Resume';return}if(!remaining||b.textContent==='Start timer')remaining=data.labs.find(l=>l.id===id).minutes*60;b.textContent='Pause';timer=setInterval(()=>{remaining=Math.max(0,remaining-1);document.getElementById(`timer-${id}`).textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;if(!remaining){clearInterval(timer);timer=null;b.textContent='Start timer';toast('Lab time complete. Move to the debrief.')}},1000)}if(b.dataset.reset){clearInterval(timer);timer=null;const id=b.dataset.reset;remaining=data.labs.find(l=>l.id===id).minutes*60;document.getElementById(`timer-${id}`).textContent=`${Math.floor(remaining/60)}:00`;document.querySelector(`[data-timer="${id}"]`).textContent='Start timer'}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.lab){state[el.dataset.lab]=el.checked;write('cityjs-coding-progress',state);updateNav($('#search').value)}if(el.dataset.evidence){evidence[el.dataset.evidence]=el.checked;write('cityjs-coding-evidence',evidence)}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){notes[el.dataset.note]=el.value;write('cityjs-coding-notes',notes)}if(el.dataset.prompt){drafts[el.dataset.prompt]=el.value;write('cityjs-coding-prompts',drafts)}});
setRoute();syncDrawer();
